var TOKEN_RE = /[A-Za-z0-9]+(?:'[A-Za-z0-9]+)*/g;

function tokenize(text) {
  var normalized = normalize(text);
  if (typeof normalized !== 'string' || normalized.length === 0) {
    return [];
  }
  var tokens = [];
  var match;
  TOKEN_RE.lastIndex = 0;
  while ((match = TOKEN_RE.exec(normalized)) !== null) {
    tokens.push(match[0]);
    if (match.index === TOKEN_RE.lastIndex) {
      TOKEN_RE.lastIndex += 1; // guard against zero-length loops
    }
  }
  return tokens;
}
", "pipeline.js": "function processText(text) {
  var tokens = tokenize(text);
  var frequencies = {};
  var unique = [];
  for (var i = 0; i < tokens.length; i++) {
    var t = tokens[i];
    if (!Object.prototype.hasOwnProperty.call(frequencies, t)) {
      frequencies[t] = 0;
      unique.push(t);
    }
    frequencies[t] = frequencies[t] + 1;
  }
  return {
    text: tokens.join(' '),
    tokens: tokens,
    count: tokens.length,
    unique: unique,
    frequencies: frequencies
  };
}
